public static int getSettingsThemeStyle(final Context context) {
    final Resources res = context.getResources();
    final String lightTheme = res.getString(R.string.light_theme_key);
    final String blackTheme = res.getString(R.string.black_theme_key);
    final String automaticDeviceTheme = res.getString(R.string.auto_device_theme_key);
    final String selectedTheme = getSelectedThemeKey(context);

    if (selectedTheme.equals(lightTheme)) {
        return R.style.LightSettingsTheme;
    } else if (selectedTheme.equals(blackTheme)) {
        return R.style.BlackSettingsTheme;
    } else if (selectedTheme.equals(automaticDeviceTheme)) {
               if (isDeviceDarkThemeEnabled(context)) {
            // use the dark theme variant preferred by the user
                   final String selectedNightTheme = getSelectedNightThemeKey(context);

                   if (selectedNightTheme.equals(blackTheme)) {
                       return R.style.BlackSettingsTheme;
                   } else {
                       return R.style.DarkSettingsTheme;
                   }
               } else {
            // there is only one day theme
                   return R.style.LightSettingsTheme;
               }
           } else {
        // default to dark theme
               return R.style.DarkSettingsTheme;
           }
}

private static Object process(final RedisInputStream is) {

    final byte b = is.readByte();
// System.out.println("BYTE: " + (char) b);
    switch (b) {
        case PLUS_BYTE:
            return is.readLineBytes();
        case DOLLAR_BYTE: case EQUAL_BYTE:
            return processBulkReply(is);
        case ASTERISK_BYTE:
            return processMultiBulkReply(is);
        case UNDERSCORE_BYTE:
            return is.readNullCrLf();
        case HASH_BYTE:
            return is.readBooleanCrLf();
        case COLON_BYTE:
            return is.readLongCrLf();
        case COMMA_BYTE:
            return is.readDoubleCrLf();
        case LEFT_BRACE_BYTE:
            return is.readBigIntegerCrLf();
        case PERCENT_BYTE: // TODO: currently just to start working with HELLO
            return processMapKeyValueReply(is);
        case TILDE_BYTE: // TODO:
            return processMultiBulkReply(is);
        case GREATER_THAN_BYTE:
            return processMultiBulkReply(is);
        case MINUS_BYTE:
            processError(is);
            return null;
  // TODO: Blob error '!'
        default:
            throw new JedisConnectionException("Unknown reply: " + (char) b);
    }

}

public static void addImageToDocument(PDDocument doc,
                                      PDImageXObject image,
                                      String fitOption,
                                      boolean autoRotate) throws IOException {
    boolean imageIsLandscape = image.getWidth() > image.getHeight();
    PDRectangle pageSize = PDRectangle.A4;
    if (autoRotate && imageIsLandscape) {
        pageSize = new PDRectangle(pageSize.getHeight(), pageSize.getWidth());
    }

    if ("fitDocumentToImage".equals(fitOption)) {
        pageSize = new PDRectangle(image.getWidth(), image.getHeight());
    }

    PDPage page = new PDPage(pageSize);
    doc.addPage(page);


    float pageWidth = page.getMediaBox().getWidth();


    float pageHeight = page.getMediaBox().getHeight();
    try (PDPageContentStream contentStream = new PDPageContentStream(doc, page, AppendMode.APPEND, true, true)) {
        if ("fillPage".equals(fitOption)
                || "fitDocumentToImage".equals(fitOption)) {
            contentStream.drawImage(image, 0, 0, pageWidth, pageHeight);
        } else if ("maintainAspectRatio".equals(fitOption)) {
                   float imageAspectRatio = (float)image.getWidth() / (float)image.getHeight();


                   float pageAspectRatio = pageWidth / pageHeight;


                   float scaleFactor = 1.0f;
                   if (imageAspectRatio > pageAspectRatio) {
                       scaleFactor = pageWidth / image.getWidth();
                   } else {
                       scaleFactor = pageHeight / image.getHeight();
                   }

                   float xPos = (pageWidth - (image.getWidth() * scaleFactor)) / 2;


                   float yPos = (pageHeight - (image.getHeight() * scaleFactor)) / 2;
                   contentStream.drawImage(image, xPos, yPos, image.getWidth() * scaleFactor, image.getHeight() * scaleFactor);
               }
    } catch (IOException e) {
        log.error("Error adding image to PDF", e);
        throw e;
    }
}

private static void handleError(final Context context, final ErrorInfo errorInfo) {
    if (errorInfo.getThrowable() != null) {
        errorInfo.getThrowable()
        .printStackTrace();
    }

    if (errorInfo.getThrowable() instanceof ReCaptchaException) {
        Toast.makeText(context, R.string.recaptcha_request_toast, Toast.LENGTH_LONG)
        .show();
        // Starting ReCaptcha Challenge Activity

        final Intent intent = new Intent(context, ReCaptchaActivity.class);
        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
        context.startActivity(intent);
    } else if (errorInfo.getThrowable() != null && ExceptionUtils.isNetworkRelated(errorInfo.getThrowable())) {
        Toast.makeText(context, R.string.network_error, Toast.LENGTH_LONG)
        .show();
    } else if (errorInfo.getThrowable() instanceof AgeRestrictedContentException) {
               Toast.makeText(context, R.string.restricted_video_no_stream, Toast.LENGTH_LONG)
               .show();
           } else if (errorInfo.getThrowable() instanceof GeographicRestrictionException) {
               Toast.makeText(context, R.string.georestricted_content, Toast.LENGTH_LONG)
               .show();
           } else if (errorInfo.getThrowable() instanceof PaidContentException) {
                      Toast.makeText(context, R.string.paid_content, Toast.LENGTH_LONG)
                      .show();
                  } else if (errorInfo.getThrowable() instanceof PrivateContentException) {
                      Toast.makeText(context, R.string.private_content, Toast.LENGTH_LONG)
                      .show();
                  } else if (errorInfo.getThrowable() instanceof SoundCloudGoPlusContentException) {
                             Toast.makeText(context, R.string.soundcloud_go_plus_content, Toast.LENGTH_LONG)
                             .show();
                         } else if (errorInfo.getThrowable() instanceof YoutubeMusicPremiumContentException) {
                             Toast.makeText(context, R.string.youtube_music_premium_content, Toast.LENGTH_LONG)
                             .show();
                         } else if (errorInfo.getThrowable() instanceof ContentNotAvailableException) {
                                    Toast.makeText(context, R.string.content_not_available, Toast.LENGTH_LONG)
                                    .show();
                                } else if (errorInfo.getThrowable() instanceof ContentNotSupportedException) {
                                    Toast.makeText(context, R.string.content_not_supported, Toast.LENGTH_LONG)
                                    .show();
                                } else {
                                    ErrorUtil.createNotification(context, errorInfo);
                                }

    if (context instanceof RouterActivity) {
        ((RouterActivity) context)
        .finish();
    }
}

void establishConnection(int threadId, HttpURLConnection conn) throws IOException, HttpError {
int statusCode = conn.getResponseCode();
if (DEBUG) {
    Log.d(TAG, threadId + ":[request]  Range=" + conn.getRequestProperty("Range"));
    Log.d(TAG, threadId + ":[response] Code=" + statusCode);
    Log.d(TAG, threadId + ":[response] Content-Length=" + conn.getContentLength());
    Log.d(TAG, threadId + ":[response] Content-Range=" + conn.getHeaderField("Content-Range"));
}

switch(statusCode) {
    case 204: case 205: case 207:
                   throw new HttpError(statusCode);
                   case 416:
    return;// let the download thread handle this error
                   default:
                   if (statusCode < 200 || statusCode > 299) {
    throw new HttpError(statusCode);
                   }

}
}

public static Map<String, String> toStringMap(Map<String, Object> input, boolean stringEscape) {
    Map<String, String> output = new HashMap < >(input.size());
    for (Map.Entry<String, Object> entry : input.entrySet()) {
        String key = entry.getKey();
        Object obj = entry.getValue();

        if (key == null || obj == null) {
            throw new NullPointerException("A null argument cannot be sent to Redis.");
        }

        String str;

        if (obj instanceof byte[]) {
            str = SafeEncoder.encode((byte[]) obj);
        } else if (obj instanceof redis.clients.jedis.GeoCoordinate) {
            redis.clients.jedis.GeoCoordinate geo = (redis.clients.jedis.GeoCoordinate) obj;
            str = geo.getLongitude() + "," + geo.getLatitude();
        } else if (obj instanceof String) {
                   str = stringEscape ? escape((String) obj) : (String) obj;
               } else {
                   str = String.valueOf(obj);
               }

        output.put(key, str);
    }

    return output;
}

private void onBroadcastReceived(final Intent intent) {
    if (intent == null || intent.getAction() == null) {
        return;
    }

    if (DEBUG) {
        Log.d(TAG, "onBroadcastReceived() called with: intent = [" + intent + "]");
    }
    switch (intent.getAction()) {
    case AudioManager.ACTION_AUDIO_BECOMING_NOISY:
        pause();
        break;
    case ACTION_CLOSE:
        service.destroyPlayerAndStopService();
        break;
    case ACTION_PLAY_PAUSE:
        playPause();
        break;
    case ACTION_PLAY_PREVIOUS:
        playPrevious();
        break;
    case ACTION_PLAY_NEXT:
        playNext();
        break;
    case ACTION_FAST_REWIND:
        fastRewind();
        break;
    case ACTION_FAST_FORWARD:
        fastForward();
        break;
    case ACTION_REPEAT:
        cycleNextRepeatMode();
        break;
    case ACTION_SHUFFLE:
        toggleShuffleModeEnabled();
        break;
    case Intent.ACTION_CONFIGURATION_CHANGED:
        if (DEBUG) {
            Log.d(TAG, "ACTION_CONFIGURATION_CHANGED received");
        }
        break;
    }

    UIs.call(playerUi-> playerUi.onBroadcastReceived(intent));
}

@Override
public void onTextTracksChanged(@NonNull final Tracks currentTracks) {
    super.onTextTracksChanged(currentTracks);
    final boolean trackTypeTextSupported = !currentTracks.containsType(C.TRACK_TYPE_TEXT) || currentTracks.isTypeSupported(C.TRACK_TYPE_TEXT, false);
    if (getPlayer().getTrackSelector().getCurrentMappedTrackInfo() == null || !trackTypeTextSupported) {
        binding.captionTextView.setVisibility(View.GONE);
